column3:
{ UNIQUE ( <column_name> [, ... ] )
| PRIMARY KEY ( <column_name> [, ... ] )
| FOREIGN KEY (<column_name> [, ... ] ) REFERENCES <reftable> [ ( <refcolumn> ) ] }

[ SETTINGS (
  { S3_BUCKET '<bucket>' | TAGS '<string>' | KMS_KEY_ID '<kms_string>' | S3_GARBAGE_COLLECT { ON | OFF }
  | MAX_CELLS <integer> | MAX_RUNTIME <integer> | HORIZON <integer> | FREQUENCY <integer>
  | PERCENTILES '<string>' | MAX_BATCH_ROWS <integer> } [, ...]
) ]
